let mismatches = 0;
function check(y, m, d, dur) {
  const a = DateTime.fromObject({ year: y, month: m, day: d }, { zone: "utc" }).plus(dur);
  const b = DateTime.fromObject({ year: y + 400, month: m, day: d }, { zone: "utc" }).plus(dur);
  if (!a.isValid || !b.isValid) {
    if (a.isValid !== b.isValid) {
      console.log("VALIDITY MISMATCH", y, m, d, JSON.stringify(dur), a.isValid, b.isValid);
      mismatches++;
    }
    return;
  }
  const same =
    a.year === b.year - 400 && a.month === b.month && a.day === b.day;
  if (!same) {
    console.log(
      "MISMATCH",
      `base=${y}-${m}-${d}`,
      JSON.stringify(dur),
      "got",
      a.toISODate(),
      "expected",
      `${b.year - 400}-${String(b.month).padStart(2, "0")}-${String(b.day).padStart(2, "0")}`
    );
    mismatches++;
  }
}

