import { Duration } from "./src/luxon.js";

const units = [
  "years",
  "quarters",
  "months",
  "weeks",
  "days",
  "hours",
  "minutes",
  "seconds",
  "milliseconds"
];

// reference: convert from-unit to milliseconds using documented factors
const toMs = {
  years: 365 * 24 * 60 * 60 * 1000,
  quarters: 91 * 24 * 60 * 60 * 1000,
  months: 30 * 24 * 60 * 60 * 1000,
  weeks: 7 * 24 * 60 * 60 * 1000,
  days: 24 * 60 * 60 * 1000,
  hours: 60 * 60 * 1000,
  minutes: 60 * 1000,
  seconds: 1000,
  milliseconds: 1
};

let bad = 0;
for (const from of units) {
  for (const to of units) {
    const expected = toMs[from] / toMs[to];

    const viaAs = Duration.fromObject({ [from]: 1 }).as(to);
    const viaNormalize = Duration.fromObject({ [from]: 1 }).normalize().as(to);
    const viaShift = Duration.fromObject({ [from]: 1 }).shiftTo(to).as(to);

    const ok = v => Number.isFinite(v) && Math.abs(v - expected) < 1e-6;
    if (!ok(viaAs) || !ok(viaNormalize) || !ok(viaShift)) {
      bad++;
      console.log(
        `BAD ${from} -> ${to}: expected=${expected} as=${viaAs} normalize().as=${viaNormalize} shiftTo().as=${viaShift}`
      );
    }
  }
}

// also: normalize a two-unit duration where the smaller unit is seconds and larger is quarters
const twoUnit = Duration.fromObject({ quarters: 1, seconds: 1 }).normalize();
console.log("normalize({quarters:1, seconds:1}) =", JSON.stringify(twoUnit.toObject()));

// longterm accuracy too
let badAcc = 0;
const daysInYearAccurate = 146097.0 / 400;
const daysInMonthAccurate = 146097.0 / 4800;
const toMsAcc = {
  years: daysInYearAccurate * 86400000,
  quarters: (daysInYearAccurate / 4) * 86400000,
  months: daysInMonthAccurate * 86400000,
  weeks: 7 * 86400000,
  days: 86400000,
  hours: 3600000,
  minutes: 60000,
  seconds: 1000,
  milliseconds: 1
};
for (const from of units) {
  for (const to of units) {
    const expected = toMsAcc[from] / toMsAcc[to];
    const v = Duration.fromObject({ [from]: 1 }, { conversionAccuracy: "longterm" })
      .normalize()
      .as(to);
    if (!Number.isFinite(v) || Math.abs(v - expected) > 1e-6) {
      badAcc++;
      console.log(`BAD(longterm) ${from} -> ${to}: expected=${expected} got=${v}`);
    }
  }
}

console.log(`bad=${bad} badAcc=${badAcc}`);

